        ensures
            Self::dispatch_spec(self@, op) == result,
    ;

    fn dispatch_mut(&mut self, op: Self::WriteOperation) -> (result: Self::Response)
        ensures
            Self::dispatch_mut_spec(old(self)@, op) == (final(self)@, result),
    ;

